import{_ as t,o as n,c as o,a2 as a}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"Types of finance projects","description":"","frontmatter":{"title":"Types of finance projects"},"headers":[],"relativePath":"docs/personal-finance/types-of-finance-projects.md","filePath":"docs/personal-finance/types-of-finance-projects.md","lastUpdated":1790284433000}'),r={name:"docs/personal-finance/types-of-finance-projects.md"};function i(s,e,c,p,f,l){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="types-of-finance-projects" tabindex="-1">Types of finance projects <a class="header-anchor" href="#types-of-finance-projects" aria-label="Permalink to &quot;Types of finance projects&quot;">​</a></h1><p>OrbySystems offers a few different kinds of finance project, each suited to a different part of your financial picture. You can create more than one, and combine them later.</p><ul><li><strong>Income/Spending</strong> — for everyday checking and credit card activity. Right choice if you mainly want to understand where your money goes.</li><li><strong>Investment</strong> — for brokerage accounts: holdings, trades, and performance. Right choice if you&#39;re tracking an investment portfolio.</li><li><strong>Fixed Assets</strong> — for things no bank statement reports: a house, a car, private company stock, and the loans against them, entered by hand. Right choice if you own real estate or other assets with a loan attached.</li><li><strong>General Documents</strong> — plain chat over documents, with no built-in financial analyses. Right choice for anything outside personal finance.</li><li><strong>Combined Finance</strong> — brings other finance projects together into one net-worth view. Right choice once you have two or more of the above and want to see them as a whole.</li></ul><h2 id="a-typical-setup" tabindex="-1">A typical setup <a class="header-anchor" href="#a-typical-setup" aria-label="Permalink to &quot;A typical setup&quot;">​</a></h2><p>Many users end up with one Income/Spending project, one Investment project, and a Fixed Assets project for a home or car loan — then a single Combined Finance project layered on top to see everything together. See <a href="/docs/personal-finance/combined-finance">Combined finance</a> for how that works.</p>',5)])])}const m=t(r,[["render",i]]);export{h as __pageData,m as default};
